using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging.Abstractions;using VanAn.CoreHub.Infrastructure;using VanAn.CoreHub.Infrastructure.Seed;using VanAn.CoreHub.Services;using VanAn.CoreHub.Tests.TestInfrastructure;using VanAn.Shared.Domain;using Xunit;namespace VanAn.Core.Tests.Services;/// <summary>/// VAS Wave 7 — Multi-tenant isolation tests./// Verifies that data from tenant A does not leak into tenant B's reports./// Uses VasSampleDataSeeder (tenant A) + a fresh random tenant B (no data)./// </summary>[Trait("Category", "VASMultiTenant")]public class VasMultiTenantTests{    private async Task<(VanAnDbContext db, BalanceSheetService bsSvc, IncomeStatementService isSvc, CashFlowStatementService cfSvc, TrialBalanceService tbSvc)> SetupAsync()    {        TestContextScope scope = VanAnDbContextTestFactory.Create();        scope.TenantProvider?.SetTenant(VasSampleDataSeeder.VasEnterpriseTenantGuid);        VanAnDbContext db = scope.Context;        _ = await AccountChartSeeder.SeedAsync(db, NullLogger.Instance);        _ = await VasSampleDataSeeder.SeedAsync(db);        var chartSvc = new AccountChartService(db, NullLogger<AccountChartService>.Instance);        return (            db,            new BalanceSheetService(db, chartSvc, NullLogger<BalanceSheetService>.Instance),            new IncomeStatementService(db, chartSvc, NullLogger<IncomeStatementService>.Instance),            new CashFlowStatementService(db, chartSvc, NullLogger<CashFlowStatementService>.Instance),            new TrialBalanceService(db, chartSvc, NullLogger<TrialBalanceService>.Instance)        );    }    // W7-MT1: Tenant A (seeded) → BS has data; Tenant B (empty) → BS has no data.    [Fact]    public async Task W7_MT1_BalanceSheet_TenantA_HasData_TenantB_Empty()    {        var (_, bsSvc, _, _, _) = await SetupAsync();        var period = new AccountingPeriod(2026, 6);        var standard = AccountingStandard.TT133_2016;        BalanceSheet bsA = await bsSvc.GenerateAsync(VasSampleDataSeeder.VasEnterpriseTenantId, period, standard);        BalanceSheet bsB = await bsSvc.GenerateAsync(new TenantId(Guid.NewGuid()), period, standard);        Assert.NotEmpty(bsA.Assets);        Assert.True(bsA.TotalAssetsEnding > 0);        Assert.Empty(bsB.Assets);        Assert.Equal(0m, bsB.TotalAssetsEnding);    }    // W7-MT2: Tenant A IS has revenue; Tenant B IS has zero revenue.    [Fact]    public async Task W7_MT2_IncomeStatement_TenantA_HasRevenue_TenantB_Zero()    {        var (_, _, isSvc, _, _) = await SetupAsync();        var period = new AccountingPeriod(2026, 6);        var standard = AccountingStandard.TT133_2016;        IncomeStatement isA = await isSvc.GenerateAsync(VasSampleDataSeeder.VasEnterpriseTenantId, period, standard);        IncomeStatement isB = await isSvc.GenerateAsync(new TenantId(Guid.NewGuid()), period, standard);        Assert.True(isA.TotalRevenueEnding > 0);        Assert.Equal(0m, isB.TotalRevenueEnding);        Assert.Equal(0m, isB.NetProfitEnding);    }    // W7-MT3: Tenant A CF has cash flow; Tenant B CF has zero.    [Fact]    public async Task W7_MT3_CashFlow_TenantA_HasFlow_TenantB_Zero()    {        var (_, _, _, cfSvc, _) = await SetupAsync();        var period = new AccountingPeriod(2026, 6);        var standard = AccountingStandard.TT133_2016;        CashFlowStatement cfA = await cfSvc.GenerateAsync(VasSampleDataSeeder.VasEnterpriseTenantId, period, standard);        CashFlowStatement cfB = await cfSvc.GenerateAsync(new TenantId(Guid.NewGuid()), period, standard);        Assert.True(cfA.ClosingCash > 0);        Assert.Equal(0m, cfB.OpeningCash);        Assert.Equal(0m, cfB.ClosingCash);        Assert.Equal(0m, cfB.NetChange);    }    // W7-MT4: Tenant A TB has accounts; Tenant B TB is empty.    [Fact]    public async Task W7_MT4_TrialBalance_TenantA_HasAccounts_TenantB_Empty()    {        var (_, _, _, _, tbSvc) = await SetupAsync();        var period = new AccountingPeriod(2026, 6);        var standard = AccountingStandard.TT133_2016;        TrialBalance tbA = await tbSvc.GenerateAsync(VasSampleDataSeeder.VasEnterpriseTenantId, period, standard);        TrialBalance tbB = await tbSvc.GenerateAsync(new TenantId(Guid.NewGuid()), period, standard);        Assert.NotEmpty(tbA.Accounts);        Assert.True(tbA.TotalDebit > 0);        Assert.Empty(tbB.Accounts);        Assert.Equal(0m, tbB.TotalDebit);        Assert.Equal(0m, tbB.TotalCredit);    }    // W7-MT5: DB-level isolation — JournalEntries query filtered by TenantId returns only tenant A entries.    [Fact]    public async Task W7_MT5_DbQuery_TenantA_OnlyReturnsTenantAEntries()    {        var (db, _, _, _, _) = await SetupAsync();        int tenantAEntries = await db.JournalEntries            .AsNoTracking()            .CountAsync(e => e.TenantId == VasSampleDataSeeder.VasEnterpriseTenantId);        int tenantBEntries = await db.JournalEntries            .AsNoTracking()            .CountAsync(e => e.TenantId == new TenantId(Guid.NewGuid()));        Assert.True(tenantAEntries > 0, "Tenant A should have journal entries");        Assert.Equal(0, tenantBEntries);    }}